        ManagedChallenge = 3, //"managed_challenge"— recommended adaptive challenge.
        Whitelist = 4,        //"whitelist"        — allow-list / bypass.

    }
    ///<summary>
    ///What the rule matches against.
    ///(member -&gt; Cloudflare wire string)
    ///</summary>
    public enum TargetKind : byte
    {
        Asn = 3,     //"asn"       — Autonomous System Number, e.g. AS13335.
        Country = 4, //"country"   — ISO-3166-1 alpha-2, e.g. RU. Specials: T1 Tor, XX unknown.
        Ip = 0,      //"ip"        — single IPv4.
        Ip6 = 1,     //"ip6"       — single IPv6.
        IpRange = 2, //"ip_range"  — CIDR range (v4 or v6).

    }
}

